    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 loanID, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        require(loanID == 0, "only fresh loan slot");

        bool reverted;
        c.provideNewTermsForRoll(loanID, interest, loanToCollateral, duration); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }
}

