pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID, uint256 interest, uint256 loanToCollateral, uint256 duration) internal {
        loanID = 0;
        bool reverted;
        try c.provideNewTermsForRoll(loanID, interest, loanToCollateral, duration) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 loanID, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        _run(loanID, interest, loanToCollateral, duration);
    }

    receive() external payable {}
}
